#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= 1025 || strlen(s2) >= 1025) {
        puts("TOO_LONG");
        return 0;
    }
    int cnt1[256] = {0};
    int cnt2[256] = {0};
    for (const char *p = s1; *p; ++p) {
        if (*p == ' ') continue;
        unsigned char c = (unsigned char)*p;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        if (c >= 'a' && c <= 'z') cnt1[c]++;
    }
    for (const char *p = s2; *p; ++p) {
        if (*p == ' ') continue;
        unsigned char c = (unsigned char)*p;
        if (c >= 'A' && c <= 'Z') c = c + ('a' - 'A');
        if (c >= 'a' && c <= 'z') cnt2[c]++;
    }
    int anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) { anagram = 0; break; }
    }
    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
